 56370  void JS_DetachArrayBuffer(JSContext *ctx, JSValueConst obj)
 56371  {
 56372      JSArrayBuffer *abuf = JS_GetOpaque(obj, JS_CLASS_ARRAY_BUFFER);
 56373
 56374      if (!abuf || abuf->detached)
 56375          return;
 56376      if (abuf->free_func)
 56377          abuf->free_func(ctx->rt, abuf->opaque, abuf->data);
 56378      abuf->data = NULL;
 56379      abuf->byte_length = 0;
 56380      abuf->detached = TRUE;
 56381      js_array_buffer_update_typed_arrays(abuf);
 56382  }
