 56662  // is the typed array detached or out of bounds relative to its RAB?
 56663  // |p| must be a typed array, *not* a DataView
 56664  static BOOL typed_array_is_oob(JSObject *p)
 56665  {
 56666      JSArrayBuffer *abuf;
 56667      JSTypedArray *ta;
 56668      int len, size_elem;
 56669      int64_t end;
 56670
 56671      assert(p->class_id >= JS_CLASS_UINT8C_ARRAY);
 56672      assert(p->class_id <= JS_CLASS_FLOAT64_ARRAY);
 56673
 56674      ta = p->u.typed_array;
 56675      abuf = ta->buffer->u.array_buffer;
 56676      if (abuf->detached)
 56677          return TRUE;
 56678      len = abuf->byte_length;
 56679      if (ta->offset > len)
 56680          return TRUE;
 56681      if (ta->track_rab)
 56682          return FALSE;
 56683      if (len < (int64_t)ta->offset + ta->length)
 56684          return TRUE;
 56685      size_elem = 1 << typed_array_size_log2(p->class_id);
 56686      end = (int64_t)ta->offset + (int64_t)p->u.array.count * size_elem;
 56687      return end > len;
 56688  }
