 56690  // Be *very* careful if you touch the typed array's memory directly:
 56691  // the length is only valid until the next call into JS land because
 56692  // JS code can detach or resize the backing array buffer. Functions
 56693  // like JS_GetProperty and JS_ToIndex call JS code.
 56694  //
 56695  // Exclusively reading or writing elements with JS_GetProperty,
 56696  // JS_GetPropertyInt64, JS_SetProperty, etc. is safe because they
 56697  // perform bounds checks, as does js_get_fast_array_element.
 56698  static int js_typed_array_get_length_unsafe(JSContext *ctx, JSValueConst obj)
 56699  {
 56700      JSObject *p;
 56701      p = get_typed_array(ctx, obj);
 56702      if (!p)
 56703          return -1;
 56704      if (typed_array_is_oob(p)) {
 56705          JS_ThrowTypeErrorArrayBufferOOB(ctx);
 56706          return -1;
 56707      }
 56708      return p->u.array.count;
 56709  }
