 56423  // ES #sec-arraybuffer.prototype.transfer
 56424  static JSValue js_array_buffer_transfer(JSContext *ctx,
 56425                                          JSValueConst this_val,
 56426                                          int argc, JSValueConst *argv,
 56427                                          int transfer_to_fixed_length)
 56428  {
 56429      JSArrayBuffer *abuf;
 56430      uint64_t new_len, *pmax_len, max_len;
 56431
 56432      abuf = JS_GetOpaque2(ctx, this_val, JS_CLASS_ARRAY_BUFFER);
 56433      if (!abuf)
 56434          return JS_EXCEPTION;
 56435      if (abuf->shared)
 56436          return JS_ThrowTypeError(ctx, "cannot transfer a SharedArrayBuffer");
 56437      if (argc < 1 || JS_IsUndefined(argv[0]))
 56438          new_len = abuf->byte_length;
 56439      else if (JS_ToIndex(ctx, &new_len, argv[0]))
 56440          return JS_EXCEPTION;
 56441      if (abuf->detached)
 56442          return JS_ThrowTypeErrorDetachedArrayBuffer(ctx);
 56443      pmax_len = NULL;
 56444      if (!transfer_to_fixed_length) {
 56445          if (array_buffer_is_resizable(abuf)) { // carry over maxByteLength
 56446              max_len = abuf->max_byte_length;
 56447              if (new_len > max_len)
 56448                  return JS_ThrowTypeError(ctx, "invalid array buffer length");
 56449              // TODO(bnoordhuis) support externally managed RABs
 56450              if (abuf->free_func == js_array_buffer_free)
 56451                  pmax_len = &max_len;
 56452          }
 56453      }
 56454      /* create an empty AB */
 56455      if (new_len == 0) {
 56456          JS_DetachArrayBuffer(ctx, this_val);
 56457          return js_array_buffer_constructor2(ctx, JS_UNDEFINED, 0, pmax_len, JS_CLASS_ARRAY_BUFFER);
 56458      } else {
 56459          uint64_t old_len;
 56460          uint8_t *bs, *new_bs;
 56461          JSFreeArrayBufferDataFunc *free_func;
 56462
 56463          bs = abuf->data;
 56464          old_len = abuf->byte_length;
 56465          free_func = abuf->free_func;
 56466
 56467          /* if length mismatch, realloc. Otherwise, use the same backing buffer. */
 56468          if (new_len != old_len) {
 56469              /* XXX: we are currently limited to 2 GB */
 56470              if (new_len > INT32_MAX)
 56471                  return JS_ThrowRangeError(ctx, "invalid array buffer length");
 56472
 56473              if (free_func != js_array_buffer_free) {
 56474                  /* cannot use js_realloc() because the buffer was
 56475                     allocated with a custom allocator */
 56476                  new_bs = js_mallocz(ctx, new_len);
 56477                  if (!new_bs)
 56478                      return JS_EXCEPTION;
 56479                  memcpy(new_bs, bs, min_int(old_len, new_len));
 56480                  abuf->free_func(ctx->rt, abuf->opaque, bs);
 56481                  bs = new_bs;
 56482                  free_func = js_array_buffer_free;
 56483              } else {
 56484                  new_bs = js_realloc(ctx, bs, new_len);
 56485                  if (!new_bs)
 56486                      return JS_EXCEPTION;
 56487                  bs = new_bs;
 56488                  if (new_len > old_len)
 56489                      memset(bs + old_len, 0, new_len - old_len);
 56490              }
 56491          }
 56492          /* neuter the backing buffer */
 56493          abuf->data = NULL;
 56494          abuf->byte_length = 0;
 56495          abuf->detached = TRUE;
 56496          js_array_buffer_update_typed_arrays(abuf);
 56497          return js_array_buffer_constructor3(ctx, JS_UNDEFINED, new_len, pmax_len,
 56498                                              JS_CLASS_ARRAY_BUFFER,
 56499                                              bs, free_func,
 56500                                              NULL, FALSE);
 56501      }
 56502  }
